<?php

declare(strict_types=1);

namespace CountryQuiz;

/**
 * Read-only access to data/countries.json (generated by tools/build-data.php).
 */
final class CountryRepository
{
    /**
     * Practice areas the player can choose from, mapped to Natural Earth continent names.
     * An empty list means "every continent".
     */
    public const AREAS = [
        'world' => [],
        'europe' => ['Europe'],
        'asia' => ['Asia'],
        'africa' => ['Africa'],
        'americas' => ['North America', 'South America'],
        'north-america' => ['North America'],
        'south-america' => ['South America'],
        'oceania' => ['Oceania'],
    ];

    /** @var array<string, array<string, mixed>> Countries keyed by their code (e.g. "SWE"). */
    private array $countriesByCode = [];

    public function __construct(string $dataFilePath)
    {
        $countries = json_decode((string) file_get_contents($dataFilePath), true, 512, JSON_THROW_ON_ERROR);
        foreach ($countries as $country) {
            $this->countriesByCode[$country['code']] = $country;
        }
    }

    public static function isValidArea(string $area): bool
    {
        return array_key_exists($area, self::AREAS);
    }

    /** @return array<string, mixed>|null */
    public function find(string $code): ?array
    {
        return $this->countriesByCode[$code] ?? null;
    }

    /**
     * All countries that can be asked about in the given area.
     *
     * @return list<array<string, mixed>>
     */
    public function quizCountries(string $area = 'world'): array
    {
        $continents = self::AREAS[$area] ?? [];
        return array_values(array_filter(
            $this->countriesByCode,
            static fn (array $country): bool => $country['quiz']
                && ($continents === [] || in_array($country['continent'], $continents, true))
        ));
    }

    /**
     * Every country with at least one outline ring inside the map view, with only those rings.
     * Longitudes are shifted by ±360° where needed so the rings line up with the view
     * (matters around the 180° meridian, e.g. Russia / Alaska / Fiji).
     *
     * @param array{float, float, float, float} $view [minLongitude, minLatitude, maxLongitude, maxLatitude]
     * @return list<array{code: string, rings: list<list<array{float, float}>>}>
     */
    public function countriesInView(array $view, string $excludedCode): array
    {
        $minPointDistance = self::detailForView($view);
        $result = [];
        foreach ($this->countriesByCode as $code => $country) {
            if ($code === $excludedCode) {
                continue;
            }
            $visibleRings = [];
            foreach ($country['rings'] as $ring) {
                $shiftedRing = self::ringInsideView($ring, $view);
                if ($shiftedRing === null) {
                    continue;
                }
                // Islands smaller than one "pixel" are not worth sending.
                $thinnedRing = self::thinRing($shiftedRing, $minPointDistance);
                if (count($thinnedRing) >= 4) {
                    $visibleRings[] = $thinnedRing;
                }
            }
            if ($visibleRings !== []) {
                $result[] = ['code' => $code, 'rings' => $visibleRings];
            }
        }
        return $result;
    }

    /**
     * The country's own outline, with detail reduced to what the view can show.
     *
     * @param array{float, float, float, float} $view
     * @return list<list<array{float, float}>>
     */
    public function outlineForView(array $country, array $view): array
    {
        // Twice the detail of the surroundings, and tiny islands are kept: they belong to the answer.
        $minPointDistance = self::detailForView($view) / 2;
        return array_map(
            static function (array $ring) use ($minPointDistance): array {
                $thinnedRing = self::thinRing($ring, $minPointDistance);
                return count($thinnedRing) >= 4 ? $thinnedRing : $ring;
            },
            $country['rings']
        );
    }

    /**
     * Smallest distance (in degrees) between two outline points that is still visible.
     * The map is at most ~1000 px wide, so 1/800 of the view is below a pixel. This keeps the
     * payload small on mobile when a big country like Russia is shown.
     */
    private static function detailForView(array $view): float
    {
        return max($view[2] - $view[0], $view[3] - $view[1]) / 800;
    }

    /**
     * Drops points that are closer than $minPointDistance to the previous kept point.
     */
    private static function thinRing(array $ring, float $minPointDistance): array
    {
        $keptPoints = [$ring[0]];
        $lastKeptPoint = $ring[0];
        $lastIndex = count($ring) - 1;
        for ($index = 1; $index < $lastIndex; $index++) {
            $point = $ring[$index];
            if (abs($point[0] - $lastKeptPoint[0]) + abs($point[1] - $lastKeptPoint[1]) >= $minPointDistance) {
                $keptPoints[] = $point;
                $lastKeptPoint = $point;
            }
        }
        $keptPoints[] = $ring[$lastIndex];
        return $keptPoints;
    }

    /**
     * Returns the ring (shifted around the globe if needed) when it overlaps the view, otherwise null.
     */
    private static function ringInsideView(array $ring, array $view): ?array
    {
        $longitudes = array_column($ring, 0);
        $latitudes = array_column($ring, 1);
        $ringMinLatitude = min($latitudes);
        $ringMaxLatitude = max($latitudes);
        if ($ringMaxLatitude < $view[1] || $ringMinLatitude > $view[3]) {
            return null;
        }

        $ringMinLongitude = min($longitudes);
        $ringMaxLongitude = max($longitudes);
        foreach ([0, -360, 360] as $shift) {
            if ($ringMaxLongitude + $shift >= $view[0] && $ringMinLongitude + $shift <= $view[2]) {
                if ($shift === 0) {
                    return $ring;
                }
                return array_map(static fn (array $point): array => [$point[0] + $shift, $point[1]], $ring);
            }
        }
        return null;
    }
}
